using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DazedEffect", menuName = "Data/Battle/Effects/Enemy/Dazed Effect")]
public class DazedEffect : Effect
{
	[Header("Purify and Corrupt Actions")]
	[SerializeField]
	private PurifyAction randomPurifyAction;

	[SerializeField]
	private CorruptAction randomCorruptAction;

	public bool DiceHavePurifyCorruptNotRandomAction(Dice dice)
	{
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			BattleAction battleAction = dice.GetDiceFaces()[i].BattleAction;
			if ((battleAction is PurifyAction && !battleAction.name.Contains("RandomPurify")) || (battleAction is CorruptAction && !battleAction.name.Contains("CorruptPurify")))
			{
				return true;
			}
			if (dice.GetDiceFaces()[i].EnableSecondAction)
			{
				BattleAction secondBattleAction = dice.GetDiceFaces()[i].SecondBattleAction;
				if ((secondBattleAction is PurifyAction && !battleAction.name.Contains("RandomPurify")) || (secondBattleAction is CorruptAction && !battleAction.name.Contains("CorruptPurify")))
				{
					return true;
				}
			}
		}
		return false;
	}

	public Dice TransformIntoRandomPurifyCorruptAction(Dice dice)
	{
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			BattleAction battleAction = dice.GetDiceFaces()[i].BattleAction;
			if (battleAction is PurifyAction && !battleAction.name.Contains("RandomPurify"))
			{
				battleAction = randomPurifyAction;
			}
			else if (battleAction is CorruptAction && !battleAction.name.Contains("RandomCorrupt"))
			{
				battleAction = randomCorruptAction;
			}
			dice.GetDiceFaces()[i].BattleAction = battleAction;
			if (dice.GetDiceFaces()[i].EnableSecondAction)
			{
				BattleAction secondBattleAction = dice.GetDiceFaces()[i].SecondBattleAction;
				if (secondBattleAction is PurifyAction && !secondBattleAction.name.Contains("RandomPurify"))
				{
					secondBattleAction = randomPurifyAction;
				}
				else if (secondBattleAction is CorruptAction && !secondBattleAction.name.Contains("RandomCorrupt"))
				{
					secondBattleAction = randomCorruptAction;
				}
				dice.GetDiceFaces()[i].SecondBattleAction = secondBattleAction;
			}
		}
		return dice;
	}
}
